'use strict';
const assert=require('node:assert/strict'),w=require('./weather-preview.js');
assert.equal(w.validDuration('5'),5);
assert.equal(w.validDuration('99'),3);
assert.equal(w.forecast('3').length,3);
assert.equal(w.forecast('7').length,7);
assert.equal(w.dayLabel(0),'Today');
assert.equal(w.dayLabel(1),'Tomorrow');
assert.equal(w.fullDate(1,new Date('2026-12-31T23:30:00Z')),'Friday 1 January');
assert.equal(w.hourly(1,new Date('2026-11-26T23:55:00Z')).length,24);
assert.deepEqual(w.hourly(99),[]);
assert.ok(w.hourly(1).every(x=>x.rain>=0&&x.rain<=100));
assert.ok(w.forecast(7).every(d=>d.low<=d.high&&w.conditions[d.condition]));
assert.notEqual(w.icon('partly','colour'),w.icon('partly','outline'));
assert.ok(w.icon('rain').includes('<svg'));
const late=new Date('2026-11-26T23:55:00Z'),next=w.hourly(0,late);
assert.equal(next.length,24);
assert.equal(next[0].time,'00:00');
assert.equal(next[0].day,1);
assert.ok(next.every(x=>x.timestamp>late.getTime()));
assert.ok(next.every((x,i)=>i===0||x.timestamp>next[i-1].timestamp));
assert.equal(w.hourly(1,late)[0].time,'00:00');
assert.equal(w.hourly(1,late).at(-1).time,'23:00');
assert.equal(w.hourly(1,new Date('2026-03-28T12:00:00Z')).length,23);
assert.equal(w.hourly(1,new Date('2026-10-24T12:00:00Z')).length,25);
assert.equal(w.summary(0).temp,w.current.temp);
assert.equal(w.summary(0).high,12);
assert.equal(w.summary(1).temp,undefined);
console.log('25 weather preview assertions passed');
